import sys, json
r = sys.stdin.buffer
w = sys.stdout.buffer
def send(obj):
    body = json.dumps(obj).encode()
    w.write(("Content-Length: %d\r\n\r\n" % len(body)).encode() + body)
    w.flush()
while True:
    headers = {}
    while True:
        line = r.readline()
        if not line: sys.exit(0)
        if line in (b"\r\n", b"\n"): break
        key, value = line.decode().split(":", 1)
        headers[key.lower()] = value.strip()
    msg = json.loads(r.read(int(headers["content-length"])))
    if msg.get("method") == "initialize":
        send({"jsonrpc":"2.0","id":msg["id"],"result":{"capabilities":{}}})
    if msg.get("method") in ("textDocument/didOpen","textDocument/didChange"):
        doc = msg["params"]["textDocument"]
        send({"jsonrpc":"2.0","method":"textDocument/publishDiagnostics","params":{"uri":doc["uri"],"diagnostics":[{"range":{"start":{"line":0,"character":0}},"severity":1,"message":"version %s" % doc["version"]}]}})
